-- Ghana Studies (10 questions)
('q_bece_soc_2024_01', 'topic_bece_ghana', 'subj_bece_social', 'Ghana gained independence in:', 'multiple_choice', '["A. 1947", "B. 1957", "C. 1960", "D. 1966"]', 'B', 'Ghana became independent on March 6, 1957.', 'easy', 1, 60),
('q_bece_soc_2024_02', 'topic_bece_ghana', 'subj_bece_social', 'The first President of Ghana was:', 'multiple_choice', '["A. J.B. Danquah", "B. Kwame Nkrumah", "C. Jerry Rawlings", "D. John Kufuor"]', 'B', 'Dr. Kwame Nkrumah became Ghana''s first president in 1960.', 'easy', 1, 60),
('q_bece_soc_2024_03', 'topic_bece_ghana', 'subj_bece_social', 'The capital city of Ghana is:', 'multiple_choice', '["A. Kumasi", "B. Tamale", "C. Accra", "D. Cape Coast"]', 'C', 'Accra is the capital and largest city of Ghana.', 'easy', 1, 60),
('q_bece_soc_2024_04', 'topic_bece_ghana', 'subj_bece_social', 'Ghana is located in which part of Africa?', 'multiple_choice', '["A. East Africa", "B. West Africa", "C. North Africa", "D. South Africa"]', 'B', 'Ghana is located in West Africa along the Gulf of Guinea.', 'easy', 1, 60),
('q_bece_soc_2024_05', 'topic_bece_ghana', 'subj_bece_social', 'The national flag of Ghana has which colors?', 'multiple_choice', '["A. Red, white, blue", "B. Green, yellow, red", "C. Red, gold, green", "D. Blue, gold, white"]', 'C', 'The Ghana flag has red, gold, and green with a black star.', 'easy', 1, 60),
('q_bece_soc_2024_06', 'topic_bece_ghana', 'subj_bece_social', 'The largest man-made lake in Ghana is:', 'multiple_choice', '["A. Lake Bosomtwe", "B. Lake Volta", "C. Lake Victoria", "D. Lake Chad"]', 'B', 'Lake Volta is the world''s largest man-made lake by surface area.', 'easy', 1, 60),
('q_bece_soc_2024_07', 'topic_bece_ghana', 'subj_bece_social', 'How many regions does Ghana currently have?', 'multiple_choice', '["A. 10", "B. 12", "C. 14", "D. 16"]', 'D', 'Ghana has 16 regions after the 2018 referendum.', 'medium', 1, 60),
('q_bece_soc_2024_08', 'topic_bece_ghana', 'subj_bece_social', 'The national anthem of Ghana is:', 'multiple_choice', '["A. God Bless Our Homeland Ghana", "B. Ghana Forever", "C. Arise Ghana", "D. Ghana, Land of Freedom"]', 'A', '"God Bless Our Homeland Ghana" is the national anthem.', 'easy', 1, 60),
('q_bece_soc_2024_09', 'topic_bece_ghana', 'subj_bece_social', 'Which ethnic group is predominantly found in the Ashanti Region?', 'multiple_choice', '["A. Ga-Adangbe", "B. Ewe", "C. Akan", "D. Dagomba"]', 'C', 'The Akan people, particularly Ashantis, dominate the Ashanti Region.', 'easy', 1, 60),
('q_bece_soc_2024_10', 'topic_bece_ghana', 'subj_bece_social', 'The currency of Ghana is:', 'multiple_choice', '["A. Naira", "B. Cedi", "C. Franc", "D. Dollar"]', 'B', 'The Ghana Cedi (GH₵) is the official currency.', 'easy', 1, 60),

-- Civics and Governance (10 questions)
('q_bece_soc_2024_11', 'topic_bece_civics', 'subj_bece_social', 'The head of the Executive arm of government in Ghana is the:', 'multiple_choice', '["A. Chief Justice", "B. Speaker of Parliament", "C. President", "D. Attorney General"]', 'C', 'The President heads the Executive branch.', 'easy', 1, 60),
('q_bece_soc_2024_12', 'topic_bece_civics', 'subj_bece_social', 'How many Members of Parliament (MPs) are there in Ghana?', 'multiple_choice', '["A. 200", "B. 230", "C. 275", "D. 300"]', 'C', 'Ghana''s Parliament has 275 elected members.', 'medium', 1, 60),
('q_bece_soc_2024_13', 'topic_bece_civics', 'subj_bece_social', 'The right to vote is also known as:', 'multiple_choice', '["A. Franchise", "B. Freedom", "C. Justice", "D. Liberty"]', 'A', 'Suffrage or franchise is the right to vote in elections.', 'easy', 1, 60),
('q_bece_soc_2024_14', 'topic_bece_civics', 'subj_bece_social', 'Which body is responsible for conducting elections in Ghana?', 'multiple_choice', '["A. Ghana Police Service", "B. Electoral Commission", "C. CHRAJ", "D. Parliament"]', 'B', 'The Electoral Commission of Ghana organizes elections.', 'easy', 1, 60),
('q_bece_soc_2024_15', 'topic_bece_civics', 'subj_bece_social', 'A citizen has the responsibility to:', 'multiple_choice', '["A. Break the law", "B. Pay taxes", "C. Avoid voting", "D. Ignore national issues"]', 'B', 'Paying taxes is a key civic responsibility.', 'easy', 1, 60),
('q_bece_soc_2024_16', 'topic_bece_civics', 'subj_bece_social', 'The Judiciary is headed by the:', 'multiple_choice', '["A. President", "B. Speaker", "C. Chief Justice", "D. Attorney General"]', 'C', 'The Chief Justice heads the Judiciary.', 'easy', 1, 60),
('q_bece_soc_2024_17', 'topic_bece_civics', 'subj_bece_social', 'CHRAJ stands for:', 'multiple_choice', '["A. Commission on Human Rights and Administrative Justice", "B. Council on Human Rights and Justice", "C. Committee on Human Rights and Justice", "D. Center for Human Rights and Justice"]', 'A', 'CHRAJ protects human rights and investigates injustice.', 'medium', 1, 90),
('q_bece_soc_2024_18', 'topic_bece_civics', 'subj_bece_social', 'Local government at the district level is headed by the:', 'multiple_choice', '["A. Regional Minister", "B. DCE/MCE", "C. MP", "D. Chief"]', 'B', 'District/Metropolitan Chief Executives head local government.', 'easy', 1, 60),
('q_bece_soc_2024_19', 'topic_bece_civics', 'subj_bece_social', 'Which document contains the fundamental laws of Ghana?', 'multiple_choice', '["A. The Gazette", "B. The Constitution", "C. The Manifesto", "D. The Decree"]', 'B', 'The 1992 Constitution is the supreme law of Ghana.', 'easy', 1, 60),
('q_bece_soc_2024_20', 'topic_bece_civics', 'subj_bece_social', 'Independence Day in Ghana is celebrated on:', 'multiple_choice', '["A. January 1", "B. March 6", "C. July 1", "D. December 31"]', 'B', 'Ghana celebrates Independence Day on March 6th.', 'easy', 1, 60),

-- Basic Economics (10 questions)
('q_bece_soc_2024_21', 'topic_bece_economics', 'subj_bece_social', 'The main export of Ghana is:', 'multiple_choice', '["A. Oil", "B. Gold", "C. Diamonds", "D. Coffee"]', 'B', 'Gold is Ghana''s leading export commodity.', 'easy', 1, 60),
('q_bece_soc_2024_22', 'topic_bece_economics', 'subj_bece_social', 'A market where buyers and sellers meet is called:', 'multiple_choice', '["A. Factory", "B. Warehouse", "C. Market", "D. Office"]', 'C', 'A market is where goods and services are exchanged.', 'easy', 1, 60),
('q_bece_soc_2024_23', 'topic_bece_economics', 'subj_bece_social', 'Barter trade involves:', 'multiple_choice', '["A. Using money", "B. Exchanging goods for goods", "C. Using credit cards", "D. Online banking"]', 'B', 'Barter is the direct exchange of goods without money.', 'easy', 1, 60),
('q_bece_soc_2024_24', 'topic_bece_economics', 'subj_bece_social', 'Human resources refer to:', 'multiple_choice', '["A. Machines", "B. Money", "C. People/Labor", "D. Buildings"]', 'C', 'Human resources are the people who work to produce goods.', 'easy', 1, 60),
('q_bece_soc_2024_25', 'topic_bece_economics', 'subj_bece_social', 'Cocoa is mainly grown in which region of Ghana?', 'multiple_choice', '["A. Northern Region", "B. Upper East Region", "C. Western Region", "D. Greater Accra"]', 'C', 'The Western Region is a major cocoa-producing area.', 'medium', 1, 60),
('q_bece_soc_2024_26', 'topic_bece_economics', 'subj_bece_social', 'Saving money helps to:', 'multiple_choice', '["A. Increase poverty", "B. Prepare for future needs", "C. Waste resources", "D. Cause inflation"]', 'B', 'Saving provides financial security for the future.', 'easy', 1, 60),
('q_bece_soc_2024_27', 'topic_bece_economics', 'subj_bece_social', 'Which sector involves farming and fishing?', 'multiple_choice', '["A. Primary sector", "B. Secondary sector", "C. Tertiary sector", "D. Quaternary sector"]', 'A', 'The primary sector involves extraction of raw materials.', 'easy', 1, 60),
('q_bece_soc_2024_28', 'topic_bece_economics', 'subj_bece_social', 'The Bank of Ghana is responsible for:', 'multiple_choice', '["A. Building roads", "B. Printing currency", "C. Teaching students", "D. Making laws"]', 'B', 'The central bank controls monetary policy and currency.', 'easy', 1, 60),
('q_bece_soc_2024_29', 'topic_bece_economics', 'subj_bece_social', 'Unemployment means:', 'multiple_choice', '["A. Having two jobs", "B. Working overtime", "C. Having no job", "D. Being retired"]', 'C', 'Unemployment is the state of being without work.', 'easy', 1, 60),
('q_bece_soc_2024_30', 'topic_bece_economics', 'subj_bece_social', 'Tourism is an example of which sector?', 'multiple_choice', '["A. Primary", "B. Secondary", "C. Tertiary", "D. None"]', 'C', 'Tourism is a service industry (tertiary sector).', 'easy', 1, 60),

