('q_bece_soc_2024_39', 'topic_bece_geography', 'subj_bece_social', 'Climate refers to:', 'multiple_choice', '["A. Daily weather conditions", "B. Weather over a long period", "C. Temperature only", "D. Rainfall only"]', 'B', 'Climate is the average weather pattern over many years.', 'easy', 1, 60),
