('q_bece_soc_2023_01', 'topic_bece_ghana', 'subj_bece_social', 'Before independence, Ghana was called:', 'multiple_choice', '["A. Ivory Coast", "B. Gold Coast", "C. Slave Coast", "D. Pepper Coast"]', 'B', 'Ghana was known as Gold Coast during colonial rule.', 'easy', 1, 60),
