('q_bece_soc_2023_19', 'topic_bece_civics', 'subj_bece_social', 'Child labor is:', 'multiple_choice', '["A. Good for children", "B. A form of child abuse", "C. Legal everywhere", "D. Encouraged in schools"]', 'B', 'Child labor exploits children and denies them rights.', 'easy', 1, 60),
